From 7c2e01b7e427e42c2456d3da7b758b2835e0da5f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 00:45:24 +0100
Subject: [PATCH] daemon: don't warn again about a low peripheral battery that
 comes back

A stylus disappears and reappears as it leaves and enters the tablet's
range, and each time it came back with a low battery a new warning was
shown. Remember each device's last charge, warn only when it gets low.

BUG: 527371
---
 daemon/powerdevilcore.cpp | 15 ++++++++++++++-
 daemon/powerdevilcore.h   |  4 ++++
 2 files changed, 18 insertions(+), 1 deletion(-)

diff --git a/daemon/powerdevilcore.cpp b/daemon/powerdevilcore.cpp
index 33badced8..d470ee79a 100644
--- a/daemon/powerdevilcore.cpp
+++ b/daemon/powerdevilcore.cpp
@@ -450,11 +450,19 @@ void Core::onDeviceAdded(const QString &udi)
     } else { // non-power supply batteries are treated separately
         m_peripheralBatteriesPercent[udi] = b->chargePercent();

+        const QString id = device.vendor() + device.product() + b->serial();
+        m_peripheralBatteryIds[udi] = id;
+        // don't warn again about a device that was already low when it went away
+        const int previousPercent = m_lastPeripheralBatteriesPercent.value(id, 1000 /* so current is always lower than previous */);
+        if (b->chargePercent() > 0) {
+            m_lastPeripheralBatteriesPercent[id] = b->chargePercent();
+        }
+
         // notify the user about the empty mouse/keyboard when plugging it in; don't when
         // notifications aren't ready yet so we avoid showing them ontop of ksplash;
         // also we'll notify about all devices when notifications are ready anyway
         if (m_notificationsReady) {
-            emitBatteryChargePercentNotification(b->chargePercent(), 1000 /* so current is always lower than previous */, udi);
+            emitBatteryChargePercentNotification(b->chargePercent(), previousPercent, udi);
         }
     }

@@ -492,8 +500,13 @@ void Core::onDeviceRemoved(const QString &udi)

     qCDebug(POWERDEVIL) << "Battery with UDI" << udi << "has been removed";

+    if (const int percent = m_peripheralBatteriesPercent.value(udi); percent > 0) {
+        m_lastPeripheralBatteriesPercent[m_peripheralBatteryIds.value(udi)] = percent;
+    }
+
     m_batteriesPercent.remove(udi);
     m_peripheralBatteriesPercent.remove(udi);
+    m_peripheralBatteryIds.remove(udi);
     m_batteriesCharged.remove(udi);
 }

diff --git a/daemon/powerdevilcore.h b/daemon/powerdevilcore.h
index 95c8341eb..0f6802296 100644
--- a/daemon/powerdevilcore.h
+++ b/daemon/powerdevilcore.h
@@ -173,6 +173,10 @@ private:

     QHash<QString, int> m_batteriesPercent;
     QHash<QString, int> m_peripheralBatteriesPercent;
+    // Peripheral batteries can come and go (e.g. a stylus leaving the tablet's range), so
+    // remember their last charge by device rather than by UDI
+    QHash<QString, QString> m_peripheralBatteryIds;
+    QHash<QString, int> m_lastPeripheralBatteriesPercent;
     QHash<QString, bool> m_batteriesCharged;

     QPointer<KNotification> m_lowBatteryNotification;
-- 
